import {makePanel} from './panels.js';
import {skiNetwork,liftPoint,upperLiftPoint,peakSummit,summit,alpineShift} from './resort-layout.js';

// A cached vector overlay uses the same world paths as the skier and terrain.
const x=n=>260+n*1.85,z=n=>44+(n-alpineShift+365)*1.85;
const path=points=>points.map((p,i)=>`${i?'L':'M'}${x(p.x).toFixed(2)} ${z(p.z).toFixed(2)}`).join(' ');
const liftPath=point=>path(Array.from({length:65},(_,i)=>{const p=point(i/64);return{x:p[0],z:p[2]};}));
const panel=makePanel('ski-trail-map','슬로프 지도',`<svg viewBox="0 0 520 450" role="img" aria-label="좌우 리프트와 네 코스가 하단 베이스로 연결되는 슬로프 지도"><defs><linearGradient id="trail-snow" x2="0" y2="1"><stop stop-color="#c7e9f5" stop-opacity=".12"/><stop offset="1" stop-color="#e6eeef" stop-opacity=".025"/></linearGradient></defs><path d="M34 407 Q15 254 102 153 L169 49 210 24 255 42 312 18 379 67 Q458 150 478 401Z" fill="url(#trail-snow)"/>${skiNetwork.map(r=>`<path data-course="${r.id}" d="${path(r.points)}" fill="none" stroke="${r.color}" stroke-width="6" stroke-linecap="round"/>`).join('')}${[liftPoint,upperLiftPoint].map(p=>`<path d="${liftPath(p)}" fill="none" stroke="#efd5a4" stroke-width="2" stroke-dasharray="5 5"/>`).join('')}${[peakSummit,summit].map((p,i)=>`<circle cx="${x(p.x)}" cy="${z(p.z)}" r="4" fill="#fff2cf"/><text x="${x(p.x)}" y="${z(p.z)-12}" text-anchor="middle">${i?'초급 출발':'정상'}</text>`).join('')}<text x="55" y="416">초급 리프트</text><text x="365" y="416">정상 리프트</text><text x="260" y="435" text-anchor="middle">하단 베이스 · 휴식 공간</text>${skiNetwork.flatMap(r=>r.merges.filter(m=>m.with==='main').map(m=>{const p=r.points.reduce((a,b)=>Math.abs(a.z-m.z)<Math.abs(b.z-m.z)?a:b);return`<circle cx="${x(p.x)}" cy="${z(p.z)}" r="5" fill="none" stroke="#edf6f6" stroke-width="1.5"/>`;})).join('')}</svg><div class="trail-map-legend">${skiNetwork.map(r=>`<button type="button" data-trail="${r.id}" aria-pressed="false"><i style="background:${r.color}"></i><span>${r.name}</span></button>`).join('')}</div>`);
panel.dialog.querySelectorAll('[data-trail]').forEach(button=>button.onclick=()=>{const active=button.getAttribute('aria-pressed')!=='true';panel.dialog.querySelectorAll('[data-trail]').forEach(b=>b.setAttribute('aria-pressed',String(active&&b===button)));panel.dialog.querySelectorAll('[data-course]').forEach(p=>{p.style.opacity=!active||p.dataset.course===button.dataset.trail?'1':'.25';});});
export const openSkiMap=()=>panel.open();
